let editingIssue=null,editingEntry=null,entryIssue=null;
const today=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Taipei'});
issues.forEach(i=>{i.entries??=[];i.status??='觀察中';i.then??=''});
const safeLink=s=>{try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}};
window.renderIssueManager=function(){
 const opened=new Set([...document.querySelectorAll('[data-open][open]')].map(x=>x.dataset.open));
 $('#issues').innerHTML=issues.map(i=>{const linked=videos.filter(v=>matches(v,i));return `<div class="issue"><div class="issue-top"><span>${esc(i.status)} · ${i.entries.length} 筆記事</span><span>${linked.length} 部影片</span></div><h3>${esc(i.name)}</h3><p>${esc(i.keys.join(' · '))}</p><div class="issue-actions"><button data-edit="${esc(i.id)}">✎ 編輯議題</button><button data-entry="${esc(i.id)}">＋ 記事／連結</button></div><details data-open="${esc(i.id)}" ${opened.has(i.id)?'open':''}><summary>判斷、記事與來源</summary><h4>當時的判斷</h4><p>${esc(i.then||'尚未填寫')}</p><h4>現在的判斷</h4><p>${esc(i.note||'尚未填寫')}</p><h4>我的記事</h4><ol class="timeline">${[...i.entries].sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<li><div class="meta">${esc(e.date)} · ${esc(e.label)}</div><p>${esc(e.text)}</p>${(e.links||[]).filter(l=>safeLink(l.url)).map(l=>`<a class="source-link" href="${esc(safeLink(l.url))}" target="_blank" rel="noopener">↗ ${esc(l.title)}</a>`).join('')}<button data-edit-entry="${esc(e.id)}" data-owner="${esc(i.id)}">編輯</button> <button data-remove-entry="${esc(e.id)}" data-owner="${esc(i.id)}">刪除記事</button></li>`).join('')||'<p class="muted">還沒有記事，按「＋ 記事／連結」新增。</p>'}</ol><h4>相關影片</h4><ul>${linked.slice(0,4).map(v=>`<li><a href="${esc(v.url)}" target="_blank" rel="noopener">${esc(v.title)}</a></li>`).join('')||'<li>尚無符合關鍵字的影片</li>'}</ul></details><div class="links"><button data-filter="${esc(i.id)}">查看相關影片 →</button> <button data-delete="${esc(i.id)}">刪除議題</button></div></div>`}).join('');
 document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openIssueEditor(b.dataset.edit));
 document.querySelectorAll('[data-entry]').forEach(b=>b.onclick=()=>openEntry(b.dataset.entry));
 document.querySelectorAll('[data-edit-entry]').forEach(b=>b.onclick=()=>openEntry(b.dataset.owner,b.dataset.editEntry));
 document.querySelectorAll('[data-remove-entry]').forEach(b=>b.onclick=()=>{if(confirm('確定刪除此篇記事？')){let i=issues.find(i=>i.id===b.dataset.owner);i.entries=i.entries.filter(e=>e.id!==b.dataset.removeEntry);save();renderIssues()}});
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{selected=issues.find(i=>i.id===b.dataset.filter);category='全部';limit=10;renderTabs();renderNews()});
 document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('確定刪除此議題及其記事？')){issues=issues.filter(i=>i.id!==b.dataset.delete);if(selected?.id===b.dataset.delete)selected=null;save();renderIssues();renderNews()}});
};
function openIssueEditor(id){editingIssue=id||null;const i=issues.find(i=>i.id===id);$('#editor-title').textContent=i?'編輯議題':'新增追蹤議題';$('#issue-name').value=i?.name||'';$('#issue-keys').value=i?.keys.join(', ')||'';$('#issue-status').value=i?.status||'觀察中';$('#issue-then').value=i?.then||'';$('#issue-note').value=i?.note||'';$('#editor').showModal()}
function saveIssueForm(e){e.preventDefault();let name=$('#issue-name').value.trim();if(!name)return;let keys=$('#issue-keys').value.split(/[,，]/).map(x=>x.trim()).filter(Boolean);if(!keys.length)return;let i=issues.find(i=>i.id===editingIssue);if(!i){i={id:crypto.randomUUID(),entries:[]};issues.push(i)}Object.assign(i,{name,keys,status:$('#issue-status').value,then:$('#issue-then').value,note:$('#issue-note').value});save();renderIssues();renderNews();$('#editor').close()}
function openEntry(id,eid){entryIssue=id;editingEntry=eid||null;const e=issues.find(i=>i.id===id).entries.find(e=>e.id===eid);$('#entry-title').textContent=e?'編輯記事':'新增記事';$('#entry-date').value=e?.date||today();$('#entry-label').value=e?.label||'筆記';$('#entry-text').value=e?.text||'';$('#entry-links').value=(e?.links||[]).map(l=>`${l.title} | ${l.url}`).join('\n');$('#entry-error').textContent='';$('#entry-videos').innerHTML=videos.map(v=>`<div class="attachment-video"><label class="video-choice"><input type="checkbox" data-url="${esc(v.url)}" data-title="${esc(v.title)}">${esc(v.title)}</label>${chapters(v).length?`<details><summary>選擇章節（${chapters(v).length}）</summary>${chapters(v).map(c=>`<label class="video-choice chapter-choice"><input type="checkbox" data-url="${esc(c.url)}" data-title="${esc(v.title+'｜'+c.time+' '+c.title)}"><span><b>${esc(c.time)}</b> ${esc(c.title)} <a href="${esc(c.url)}" target="_blank" rel="noopener">播放 ↗</a></span></label>`).join('')}</details>`:''}</div>`).join('');$('#entry-editor').showModal()}
$('#entry-cancel').onclick=()=>$('#entry-editor').close();
$('#entry-form').onsubmit=e=>{e.preventDefault();let links=[];for(const row of $('#entry-links').value.split('\n').filter(s=>s.trim())){const pos=row.indexOf('|'),url=(pos<0?row:row.slice(pos+1)).trim(),title=pos<0?url:row.slice(0,pos).trim();const valid=safeLink(url);if(!valid){$('#entry-error').textContent='連結請使用有效的 http 或 https 網址。';return}links.push({title:title||url,url:valid})}document.querySelectorAll('#entry-videos input:checked').forEach(c=>{const url=c.dataset.url,title=c.dataset.title;if(!links.some(l=>l.url===url))links.push({title,url})});const i=issues.find(i=>i.id===entryIssue),item={id:editingEntry||crypto.randomUUID(),date:$('#entry-date').value,label:$('#entry-label').value,text:$('#entry-text').value,links};if(editingEntry)i.entries=i.entries.map(e=>e.id===editingEntry?item:e);else i.entries.push(item);save();$('#entry-editor').close();renderIssues();const detail=[...document.querySelectorAll('[data-open]')].find(d=>d.dataset.open===entryIssue);if(detail)detail.open=true};
renderIssues();load();
